# Templates retain all numeric values and source IDs.
def translate(t):
 st=t.strip()
 if st in MANUAL:return MANUAL[st]
 if '原始候选行 / Original candidate row' in t:return t.replace('原始候选行 / ','').replace('患者身份未知 / ','')
 if 'pairs · page' in t:return t.split('. 原始 metadata')[0]+'. Original metadata-row/source-ID order; no visual cherry-picking. Unreviewed means neither duplicate nor independent.'
 if 'basis index' in t:return t.replace('invalid / 无效','invalid').replace('有效 / valid','valid').replace('无效 / invalid','invalid')
 if 'ZERO FEATURE / 未有效分配' in t:return t.replace('ZERO FEATURE / 未有效分配','ZERO FEATURE / unassigned')
 if t.startswith('研究审阅图谱 ·'):return 'Research review atlas'
 if t.startswith('私有离线资料 ·'):return 'Private offline material'
 if t.startswith('Initial cluster') and (' / 保留' in t or ' / 过滤' in t):return t.replace(' / 保留','').replace(' / 过滤','')
 return None

